inline void FinishSizePrefixedTKGBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<TKG> root) {
  fbb.FinishSizePrefixed(root, TKGIdentifier());
}

inline std::unique_ptr<TKGT> UnPackTKG(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<TKGT>(GetTKG(buf)->UnPack(res));
}

inline std::unique_ptr<TKGT> UnPackSizePrefixedTKG(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<TKGT>(GetSizePrefixedTKG(buf)->UnPack(res));
}

